const zlib=require('zlib');
const SIG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
function readChunks(buf) {
if (!buf.slice(0, 8).equals(SIG)) throw new Error('Kein PNG (Signatur)');
