const item = $input.first();
const j = item.json || {};
const bin = item.binary || {};

// ============================================================
// GATE 1: Redaktions-Check
// Faellt der Text durch, entsteht KEIN Buffer-Draft. Kein Fehler,
// der Zweig laeuft einfach leer aus - die E-Mail geht trotzdem raus.
// ============================================================
if (!j.qa_passed) { return []; }

// ============================================================
// KONFIGURATION
// ============================================================
const supabaseHost = 'https://ouccmqkwgdxjnplblnzk.supabase.co';
const bucket = 'social-media';
const channelId = '6a81ec01ccaf649a67b94a2c';

if (!bin.img_1x1) { throw new Error('Buffer-Draft: Binary img_1x1 fehlt.'); }

let linkedinText = String(j.linkedin_text || '').trim();
if (!linkedinText) { throw new Error('Buffer-Draft: LinkedIn-Text fehlt.'); }

// Alte Quellen-Hinweise entfernen
linkedinText = linkedinText
  .replace(/(^|\n)\s*Quelle\s+in\s+den\s+Kommentaren\.?\s*(?=\n|$)/gi, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ============================================================
// GATE 2: harte Sperre gegen Links und gesperrte Marken im Post
// ============================================================
if (/https?:\/\/|www\./i.test(linkedinText)) {
  throw new Error('Buffer-Draft blockiert: Link im LinkedIn-Text.');
}

const hashtagTokens = String(j.linkedin_hashtags || '').split(/\s+/).map(v => v.trim()).filter(v => v.indexOf('#') === 0);
const uniqueHashtags = [...new Set(hashtagTokens)].slice(0,3);
const hashtags = uniqueHashtags.join(' ');

// ============================================================
// KEIN Quellenblock im Post-Text.
// LinkedIn drosselt Beitraege mit ausgehenden Links deutlich,
// und Fremdquellen gehoeren nicht unter einen KAPA-Beitrag.
// Die Quelle steht in link_comment_text und wird manuell als
// erster Kommentar gesetzt.
// ============================================================
const postText = [linkedinText, hashtags].filter(Boolean).join('\n\n');

const safeId = String(j.cp_id || ('cp_' + Date.now())).replace(/[^a-zA-Z0-9_-]/g, '_');
const imagePath = 'linkedin/' + safeId + '.png';
const altText = String(j.instagram_alt || j.topic || 'KAPA Digital Visual').trim().slice(0, 300);

return [{
  json: {
    ...j,
    buffer_post_text: postText,
    buffer_source_title: String(j.source || ''),
    buffer_source_url: String(j.source_url || ''),
    buffer_first_comment: String(j.link_comment_text || ''),
    buffer_alt_text: altText,
    buffer_channel_id: channelId,
    buffer_hashtags: uniqueHashtags,
    supabase_host: supabaseHost,
    storage_bucket: bucket,
    buffer_image_path: imagePath
  },
  binary: bin
}];

const upload = $json || {};
if (upload.error) {
  throw new Error('Buffer-Draft abgebrochen: Supabase-Bildupload fehlgeschlagen. ' + JSON.stringify(upload.error));
}
const p = $('Buffer Config + Draft vorbereiten').first().json;

const imageUrl = p.supabase_host + '/storage/v1/object/public/' + p.storage_bucket + '/' + p.buffer_image_path;
const q = value => JSON.stringify(String(value == null ? '' : value));

// KEIN aiAssisted-Flag: der Text ist redaktionell geprueft und wird
// nicht als maschinell erzeugt markiert.
// saveToDraft:true verhindert die automatische Veroeffentlichung.
const query = 'mutation CreateKapaLinkedInDraft {\n' +
  '  createPost(input: {\n' +
  '    text: ' + q(p.buffer_post_text) + '\n' +
  '    channelId: ' + q(p.buffer_channel_id) + '\n' +
  '    schedulingType: automatic\n' +
  '    mode: addToQueue\n' +
  '    saveToDraft: true\n' +
  '    assets: [{\n' +
  '      image: {\n' +
  '        url: ' + q(imageUrl) + '\n' +
  '        metadata: { altText: ' + q(p.buffer_alt_text) + ' }\n' +
  '      }\n' +
  '    }]\n' +
  '  }) {\n' +
  '    ... on PostActionSuccess { post { id text status } }\n' +
  '    ... on MutationError { message }\n' +
  '  }\n' +
  '}';

return [{ json: { ...p, buffer_image_url: imageUrl, buffer_query: query } }];

// ============================================================
// Fester Redaktionsplan statt rechnerischer Rotation.
// Gepflegt wird er in der Tabelle content_schedule, nicht hier.
//
// WICHTIG: Der weekday in content_schedule ist der POSTTAG, nicht
// der Lauftag. Der Flow laeuft einen Tag vorher, damit der Entwurf
// am Vorabend im Buffer liegt:
//
//   Montag    laeuft -> Slot Dienstag  -> Werkstatt & Produktion
//   Mittwoch  laeuft -> Slot Donnerstag -> Engineering & Konstruktion
//   Donnerstag laeuft -> Slot Freitag   -> Buero & Verwaltung
//
// Wer den Cron aendert, muss die Tabelle mitaendern - und umgekehrt.
// ============================================================
const rows = $input.all().map(i => i.json).filter(r => r && r.weekday != null);
const now = $now;
const runWd = now.weekday;              // 1 = Montag ... 7 = Sonntag
const postWd = now.plus({ days: 1 }).weekday;  // der Tag, fuer den produziert wird

let row = rows.find(r => Number(r.weekday) === postWd) || null;
let fallbackUsed = false;
if (!row && rows.length) {
  // Manueller Lauf an einem Tag ohne Slot: naechstliegenden Slot verwenden,
  // damit ein Test nicht ins Leere laeuft.
  row = rows.slice().sort((a, b) => Math.abs(a.weekday - postWd) - Math.abs(b.weekday - postWd))[0];
  fallbackUsed = true;
}

const pillars = String((row && row.pillars) || 'buero')
  .split(',').map(s => s.trim()).filter(Boolean);

const namen = { 1: 'Montag', 2: 'Dienstag', 3: 'Mittwoch', 4: 'Donnerstag', 5: 'Freitag', 6: 'Samstag', 7: 'Sonntag' };

return [{ json: {
  pillar: pillars[0] || 'buero',
  pillar_priority: pillars,
  slot_name: String((row && row.slot_name) || 'ohne Slot'),
  schedule_fallback: fallbackUsed,
  run_weekday: runWd,
  run_tag: namen[runWd] || String(runWd),
  post_weekday: postWd,
  post_tag: namen[postWd] || String(postWd),
  run_date: now.toISO(),
  post_date: now.plus({ days: 1 }).toISODate()
} }];

// ============================================================
// KAPA Content Studio - Themenauswahl
// Der Wochentag gibt ueber content_schedule die Saeule vor.
// Prioritaet: 1) Use-Case der Saeule des Tages
//             2) Use-Case aus den Ersatzsaeulen des Slots
//             3) Use-Case aus einer beliebigen anderen Saeule
//             4) Marketing-Idee aus den News (nur Blocklist-sauber)
// Kein Treffer -> leeres Ergebnis, der Lauf produziert nichts.
// ============================================================
const saeule = $('Saeule bestimmen').first().json;
const prio = (Array.isArray(saeule.pillar_priority) && saeule.pillar_priority.length)
  ? saeule.pillar_priority : [String(saeule.pillar || 'buero')];
const pillar = prio[0];
const slotName = String(saeule.slot_name || '');

const MOTIFS = {
  handwerk: 'Werkstatt, Baustellencontainer, Tablet auf der Werkbank, Aufmassskizze, Materiallager, Montagefahrzeug',
  fertigung: 'Werkhalle, CNC-Maschine, Messmittel und Pruefplatz, Auftragsmappe, Materialfluss, Schichtuebergabe',
  engineering: 'Konstruktionsarbeitsplatz, Zeichnungsablage, Planrolle, Revisionsstempel, Projekttafel, Datenuebergabe',
  buero: 'Buerotisch mit Belegstapel, Ablageordner, Posteingangskorb, Bildschirm mit Uebersicht, Besprechungstisch'
};
const PILLAR_LABEL = { handwerk:'Handwerk & Baustelle', fertigung:'Fertigung & Maschine', engineering:'Engineering & CAD/PDM', buero:'Buero & Verwaltung' };

// --- Blocklist ---
const rules = $('Blocklist lesen').all().map(i => i.json).filter(r => r && r.pattern);
const domains = rules.filter(r => r.match_type === 'domain').map(r => String(r.pattern).toLowerCase());
const paths   = rules.filter(r => r.match_type === 'url_path').map(r => String(r.pattern).toLowerCase());
const titleKw = rules.filter(r => r.match_type === 'title_keyword').map(r => String(r.pattern).toLowerCase());

function hostOf(url){ const m = String(url||'').match(/^https?:\/\/([^\/?#]+)/i); return m ? m[1].toLowerCase().replace(/^www\./,'') : ''; }
function pathOf(url){ const m = String(url||'').match(/^https?:\/\/[^\/?#]+([^?#]*)/i); return m ? m[1].toLowerCase() : ''; }
function blockReason(url, title){
  const h = hostOf(url), p = pathOf(url), t = String(title||'').toLowerCase();
  if (!h) return 'keine gueltige URL';
  for (const d of domains){ if (h === d || h.endsWith('.' + d)) return 'Domain gesperrt: ' + d; }
  for (const s of paths){ if (p.includes(s)) return 'Verkaufsseite: ' + s; }
  for (const k of titleKw){ if (t.includes(k)) return 'Listicle-Muster: ' + k; }
  return '';
}

// --- Dublettenschutz (45 Tage) ---
const cutoff = Date.now() - 45*86400000;
const recent = $('Bisherige Pakete lesen').all().map(i => i.json).filter(p => {
  const d = Date.parse(p.created_at || p.createdAt || '');
  return isNaN(d) ? true : d >= cutoff;
});
function norm(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9aeoeuess ]/g,' ').replace(/ +/g,' ').trim(); }
const usedTopics = new Set(recent.map(p => norm(p.topic)).filter(Boolean));
const usedRefs = new Set(recent.map(p => String(p.use_case_ref||'')).filter(Boolean));
const usedUrls = new Set(recent.map(p => { const m = String(p.sources||'').match(/https?:\/\/\S+/); return m ? hostOf(m[0]) + pathOf(m[0]) : ''; }).filter(Boolean));
function isDuplicate(topic, url, ref){
  if (ref && usedRefs.has(String(ref))) return true;
  if (usedTopics.has(norm(topic))) return true;
  if (url && usedUrls.has(hostOf(url) + pathOf(url))) return true;
  return false;
}

// ------------------------------------------------------------
// Zielgruppenfilter: KAPA spricht Handwerk, Fertigung, Ingenieur-
// bueros und Bueroorganisation an. Use-Cases fuer SaaS-Anbieter,
// Startups, Konzerne oder Entwicklerteams gehoeren nicht in einen
// KAPA-Beitrag, auch wenn der Scout sie hoch bewertet hat.
// ------------------------------------------------------------
const OFF_TARGET = /(saas|start\s?-?up|scale\s?-?up|enterprise|konzern|softwareunternehmen|software-unternehmen|softwarehaus|entwicklerteam|entwickler|developer|agentur|it-dienstleister|dienstleistungsunternehmen im it)/;
function zielgruppePasst(u){
  const blob = (String(u.target_group||'') + ' ' + String(u.name||'') + ' ' + String(u.problem||'')).toLowerCase();
  return !OFF_TARGET.test(blob);
}

// ------------------------------------------------------------
// Eignungsfilter (seit 03.09.2026): Der Redaktions-Check blockiert
// einen Beitrag hart, wenn im Text kein benanntes Dokument und kein
// benannter Arbeitsschritt vorkommt. Ein Use-Case, der selbst keines
// nennt, kann die Pruefung nicht bestehen - er faellt hier heraus,
// bevor ein Modell laeuft. Deterministisch, kostet nichts.
//
// Die Liste steht in "Redaktionsregeln" und wird von dort auch vom
// Redaktions-Check gelesen: Auswahl und Pruefung muessen dasselbe
// darunter verstehen, sonst waehlt der Flow, was er selbst verwirft.
//
// Nur auf Use-Cases angewandt. Eine News-Idee traegt einen echten
// Artikel, aus dem der Text den Beleg holen kann; ihre kurzen Felder
// sind kein taugliches Mass.
// ------------------------------------------------------------
const REGELN = $('Redaktionsregeln').first().json;
const ANKER = REGELN.anker || [];
const TECHNIK_STOP = new Set(REGELN.technik_stopwoerter || []);
function ankerTreffer(u){
  const blob = (String(u.name||'') + ' ' + String(u.problem||'') + ' ' + String(u.solution||'')).toLowerCase();
  const t = [];
  for (const a of ANKER) { if (blob.indexOf(a) >= 0) t.push(a); }
  return t;
}
function hatAnker(u){ return ankerTreffer(u).length > 0; }

// ------------------------------------------------------------
// Eignung: welcher Kandidat traegt den besten Beitrag?
//
// LinkedIn veroeffentlicht keine Rankingformel. Was es gibt, sind
// Empfehlungen fuer organische Beitraege - konkreter Einstieg statt
// Allgemeinplatz, benannter Arbeitskontext, kein Fremdprodukt, eine
// Frage am Ende. Genau diese Punkte pruefen 'Redaktions-Check' und
// 'Lesbarkeit pruefen' am fertigen Text. Die Eignung schaetzt hier
// vorab, wie gut ein Use-Case dieses Material hergibt - damit die
// Auswahl an denselben Massstaeben haengt wie die Abnahme.
//
// Der Scout-Score taugt dafuer nicht: er liegt konstant bei 8 bis 9.
// Er bleibt nur noch Stichentscheid bei gleicher Eignung.
// ------------------------------------------------------------
function hatProduktname(u){
  const toks = String(u.technology||'').split(/[^A-Za-z0-9ÄÖÜäöüß]+/);
  for (const t of toks) { if (t.length >= 4 && !TECHNIK_STOP.has(t.toLowerCase())) return true; }
  return false;
}
function eignung(u){
  const gruende = [];
  let p = 0;
  const treffer = ankerTreffer(u);
  const n = Math.min(treffer.length, 3);
  p += n * 20;
  if (n) gruende.push(n + 'x Dokument/Arbeitsschritt (' + treffer.slice(0,3).join(', ') + ')');
  if (String(u.solution||'').length >= 60) { p += 15; gruende.push('Loesungsweg beschrieben'); }
  if (String(u.problem||'').length >= 60) { p += 10; gruende.push('Problem beschrieben'); }
  const tg = String(u.target_group||'').trim().toLowerCase();
  if (tg && !/^(kleine unternehmen|unternehmen|kmu|mittelstand|allgemein)$/.test(tg)) { p += 10; gruende.push('spezifische Zielgruppe'); }
  if (!hatProduktname(u)) { p += 5; gruende.push('kein Fremdprodukt in der Vorlage'); }
  return { punkte: p, gruende: gruende };
}
function besserZuerst(a, b){
  const d = eignung(b).punkte - eignung(a).punkte;
  return d !== 0 ? d : ((b.score||0) - (a.score||0));
}

// --- Kandidaten: Use-Cases ---
const ucVorAnker = $('Use-Cases lesen').all().map(i => i.json)
  .filter(u => u && u.uc_id && (u.score || 0) >= 7)
  .filter(zielgruppePasst)
  .filter(u => !isDuplicate(u.name, '', u.uc_id));
const ucAll = ucVorAnker.filter(hatAnker);
// Sortiert wird nach Eignung, der Scout-Score ist nur noch Stichentscheid.

let pick = null;
let note = '';
for (let k = 0; k < prio.length; k++) {
  const cand = ucAll.filter(u => u.pillar === prio[k]).sort(besserZuerst)[0];
  if (cand) {
    pick = cand;
    note = (k === 0)
      ? ('Use-Case aus der Saeule des Tages (' + slotName + ')')
      : ('Ersatzsaeule des Slots ' + slotName + ': ' + prio[k] + ' - keine Use-Cases mehr in ' + pillar);
    break;
  }
}
if (!pick) {
  const cand = ucAll.filter(u => prio.indexOf(u.pillar) < 0).sort(besserZuerst)[0];
  if (cand) { pick = cand; note = 'Slot ' + slotName + ' erschoepft, Use-Case aus ' + (cand.pillar || 'ohne Zuordnung'); }
}

// --- Kandidaten: Marketing-Ideen ---
const ideas = [];
const rejected = [];
for (const it of $('Idee lesen').all().map(i => i.json).filter(x => x && x.mi_id)) {
  const reason = blockReason(it.source_url, (it.source || '') + ' ' + (it.topic || ''));
  if (reason) { rejected.push(it.mi_id + ': ' + reason); continue; }
  if (isDuplicate(it.topic, it.source_url, it.mi_id)) { rejected.push(it.mi_id + ': Dublette'); continue; }
  ideas.push(it);
}
ideas.sort((a,b) => String(a.idea_date||'').localeCompare(String(b.idea_date||'')));

// --- Auswahl ---
let out = null;
if (pick) {
  out = {
    source_mode: 'use_case',
    pillar: pick.pillar || pillar,
    ref_id: pick.uc_id, uc_id: pick.uc_id, mi_id: '__none__',
    topic: String(pick.name||''),
    target_group: String(pick.target_group||''),
    hook: '', core_message: String(pick.problem||''),
    uc_problem: String(pick.problem||''), uc_solution: String(pick.solution||''),
    uc_technology: String(pick.technology||''), uc_business_model: String(pick.business_model||''),
    content_format: 'Einzelbild', cta: '', source: '', source_url: '',
    selection_note: note
  };
} else if (ideas.length) {
  const it = ideas[0];
  out = {
    source_mode: 'news', pillar,
    ref_id: it.mi_id, uc_id: '__none__', mi_id: it.mi_id,
    topic: String(it.topic||''), target_group: String(it.target_group||''),
    hook: String(it.hook||''), core_message: String(it.core_message||''),
    uc_problem: '', uc_solution: '', uc_technology: '', uc_business_model: '',
    content_format: String(it.content_format||'Einzelbild'), cta: String(it.cta||''),
    source: String(it.source||''), source_url: String(it.source_url||''),
    selection_note: 'Keine Use-Cases mehr verfuegbar, News-Idee verwendet'
  };
}
if (!out) return [];
out.slot_name = slotName;
out.pillar_label = PILLAR_LABEL[out.pillar] || out.pillar;
out.visual_motifs = MOTIFS[out.pillar] || MOTIFS.buero;
out.available_use_cases = ucAll.length;
out.available_ohne_anker = ucVorAnker.length - ucAll.length;
if (pick) {
  const e = eignung(pick);
  out.eignung = e.punkte;
  out.eignung_gruende = e.gruende.join(' | ');
} else { out.eignung = 0; out.eignung_gruende = ''; }

// ------------------------------------------------------------
// Wochenvorschau: je Posttag der beste verfuegbare Kandidat.
// Steht in der Tagesmeldung und in der E-Mail, damit sichtbar ist,
// was an den naechsten Posttagen ansteht und wo der Pool duenn wird -
// bevor ein Lauf leer ausgeht.
// ------------------------------------------------------------
const TAGE = { 1:'Montag', 2:'Dienstag', 3:'Mittwoch', 4:'Donnerstag', 5:'Freitag', 6:'Samstag', 7:'Sonntag' };
const plan = $('Zeitplan lesen').all().map(i => i.json)
  .filter(r => r && r.weekday != null && r.active !== false)
  .sort((a,b) => Number(a.weekday) - Number(b.weekday));
const vorschau = [];
for (const r of plan) {
  const saeulen = String(r.pillars||'').split(',').map(s => s.trim()).filter(Boolean);
  let bester = null;
  for (const s of saeulen) {
    const c = ucAll.filter(u => u.pillar === s).sort(besserZuerst)[0];
    if (c) { bester = c; break; }
  }
  const anzahl = ucAll.filter(u => saeulen.indexOf(u.pillar) >= 0).length;
  vorschau.push({
    tag: TAGE[Number(r.weekday)] || String(r.weekday),
    slot: String(r.slot_name||''),
    kandidaten: anzahl,
    topic: bester ? String(bester.name||'') : '',
    uc_id: bester ? String(bester.uc_id||'') : '',
    eignung: bester ? eignung(bester).punkte : 0
  });
}
out.slot_vorschau = vorschau;
let zeilen = '';
for (const v of vorschau) {
  zeilen += v.tag + ' (' + v.slot + '): ' + (v.topic ? (v.topic + ' - Eignung ' + v.eignung) : 'kein tauglicher Kandidat') + ', ' + v.kandidaten + ' im Pool' + String.fromCharCode(10);
}
out.slot_vorschau_text = zeilen.trim();
out.available_in_slot = ucAll.filter(u => prio.indexOf(u.pillar) >= 0).length;
out.available_ideas = ideas.length;
out.rejected_ideas = rejected.slice(0,10).join(' | ');
return [{ json: out }];

// Regelbasiertes Qualitaetsgate. Der content_score des Modells ist wertlos
// (liegt konstant bei 8-9), deshalb wird hier hart gegen Regeln geprueft.
const c = $json;
const rules = $('Blocklist lesen').all().map(i => i.json).filter(r => r && r.pattern);
const blockedNames = rules
  .filter(r => r.match_type === 'domain' && ['competitor','consulting','vendor_sales'].indexOf(r.reason) >= 0)
  .map(r => String(r.pattern).toLowerCase().replace(/\.(com|de|eu|ai|io|net|au|group)$/,''))
  .filter(n => n.length >= 5);

const text = String(c.linkedin_text || '');
const lower = text.toLowerCase();
const firstLine = (text.split('\n').map(s => s.trim()).filter(Boolean)[0]) || '';
const issues = [];
const soft = [];

for (const n of blockedNames) { if (lower.indexOf(n) >= 0) issues.push('Gesperrte Marke im Text: ' + n); }
if (/https?:\/\/|www\./i.test(text)) issues.push('Link im Text');
if (/\?\s*$/.test(firstLine)) issues.push('Erster Satz ist eine Frage');
if (/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(firstLine)) issues.push('Emoji im ersten Satz');

// ------------------------------------------------------------
// Fremdprodukte: der Use-Case nennt im Feld 'technology' oft ein
// konkretes Anbieterprodukt. Das darf nicht im KAPA-Beitrag landen -
// sonst bewirbt KAPA fremde Werkzeuge unter eigenem Namen.
//
// Der Befund meldet, er blockiert nicht. Oft steht in 'technology'
// gar kein Produkt, sondern ein Allerweltsbegriff wie
// 'Bildverarbeitung'. Den koennte nur eine vollstaendige Liste
// generischer Woerter aussortieren, und die gibt es nicht. Echte
// Marken haelt die Blocklist-Pruefung weiter oben hart auf.
//
// Der Bindestrich trennt mit, sonst bliebe 'KI-gestuetzte' ein
// einziges Token, das die STOP-Liste nicht kennt.
// ------------------------------------------------------------
// Die Technik-Stoppwoerter stehen in "Redaktionsregeln" - dieselbe Quelle,
// aus der "Thema waehlen" erkennt, ob ein Use-Case einen Produktnamen
// mitbringt, den der Text spaeter nicht nennen darf.
const STOP = new Set(($('Redaktionsregeln').first().json.technik_stopwoerter) || []);
const techTokens = String(c.uc_technology || '')
  .split(/[^A-Za-z0-9ÄÖÜäöüß]+/)
  .map(t => t.trim())
  .filter(t => t.length >= 4 && !STOP.has(t.toLowerCase()));
for (const t of techTokens) {
  if (lower.indexOf(t.toLowerCase()) >= 0) { soft.push('Begriff aus dem Technologiefeld im Text: ' + t); break; }
}

const weak = ['könnte','koennte','könnten','koennten','würde','wuerde','würden','wuerden','stellen sie sich vor'];
for (const w of weak) { if (lower.indexOf(w) >= 0) { issues.push('Hypothetische Formulierung: ' + w); break; } }
const buzz = ['revolutionär','revolutionaer','gamechanger','game changer','verändert alles','veraendert alles','disruptiv','zukunft der arbeit'];
for (const b of buzz) { if (lower.indexOf(b) >= 0) { issues.push('Buzzword: ' + b); break; } }

// Zahlenpruefung: jede Zahl muss aus 'belegte_zahlen' stammen.
const belegt = String(c.belegte_zahlen || '');
const belegteZiffern = new Set((belegt.match(/\d+(?:[.,]\d+)?/g) || []).map(String));
const imText = (text.replace(/#\S+/g, '').match(/\d+(?:[.,]\d+)?/g) || []).map(String);
const erfunden = [...new Set(imText.filter(z => !belegteZiffern.has(z)))];
if (erfunden.length) issues.push('Nicht belegte Zahl(en) im Text: ' + erfunden.join(', '));
const claimWords = ['studie','studien','umfrage','laut einer','durchschnittlich','im schnitt','branchenüblich','branchenueblich'];
for (const w of claimWords) { if (lower.indexOf(w) >= 0) { issues.push('Statistik-Behauptung ohne Beleg: ' + w); break; } }
// Ausgeschriebene Mengenangaben ohne Beleg. Die Ziffernpruefung oben
// greift hier nicht: "erheblich guenstiger" enthaelt keine Zahl und ist
// trotzdem eine Behauptung.
//
// Ein Mengenwort allein reicht nicht als Befund. "Den Arbeitsalltag
// erheblich erleichtern" ist qualitativ und harmlos; erst zusammen mit
// einem messbaren Ziel in der Naehe wird daraus eine Mengenbehauptung.
// Gemessen an den 17 abgelegten Beitraegen: 3 Treffer, alle drei echte
// Behauptungen - die beiden qualitativen "erheblich" laufen durch.
//
// Weich, nicht hart: Ein durchgelassener Beitrag geht als Entwurf nach
// Buffer und wird dort von Hand freigegeben. Der Befund gehoert an die
// Stelle, wo geprueft wird; ein harter Block kostet den ganzen Posttag,
// obwohl danach ohnehin jemand draufschaut.
if (!belegt.trim()) {
  // Die Wortliste steht als Muster in "Redaktionsregeln" - dieselbe Quelle, auf
  // die sich auch Analyse- und COPY-Prompt beziehen. Fehlt das Muster, wird
  // nicht geprueft; ein leeres Muster wuerde ueberall greifen.
  const MUSTER = String(($('Redaktionsregeln').first().json.mengenwoerter_muster) || '');
  const MENGE = MUSTER ? new RegExp('\\b(' + MUSTER + ')', 'gi') : null;
  const ZIEL = /(kosten|zeit|dauer|aufwand|ressourcen|personal|fehler|quote|umsatz|produktivit(?:ä|ae)t|effizienz|senk|spar|reduzier|verk(?:ü|ue)rz|beschleunig|steiger|erh(?:ö|oe)h)/i;
  const NAEHE = 50;
  let treffer;
  while (MENGE && (treffer = MENGE.exec(text)) !== null) {
    const von = Math.max(0, treffer.index - NAEHE);
    const bis = Math.min(text.length, treffer.index + treffer[0].length + NAEHE);
    const umfeld = text.slice(von, bis);
    if (ZIEL.test(umfeld)) {
      soft.push('Mengenangabe ohne Beleg: "' + umfeld.replace(/\s+/g, ' ').trim() + '"');
      break;
    }
  }
}

// Zielgruppenpruefung im Text selbst
const offTarget = ['saas','start-up','startup','enterprise','konzern','softwareunternehmen','entwicklerteam'];
for (const o of offTarget) { if (lower.indexOf(o) >= 0) { issues.push('Zielgruppenfremder Begriff im Text: ' + o); break; } }

// Die Ankerliste steht in "Redaktionsregeln" - dieselbe Quelle, aus der
// "Thema waehlen" seinen Eignungsfilter speist. Nur so verwirft die
// Pruefung nicht, was die Auswahl vorher fuer tauglich gehalten hat.
const anchors = ($('Redaktionsregeln').first().json.anker) || [];
if (!anchors.some(a => lower.indexOf(a) >= 0)) issues.push('Kein benanntes Dokument und kein benannter Arbeitsschritt');
if (text.indexOf('?') < 0) issues.push('Keine Frage am Ende');

const len = text.length;
if (len < 500) issues.push('LinkedIn-Text zu kurz (' + len + ' Zeichen)');
if (len > 1600) issues.push('LinkedIn-Text zu lang (' + len + ' Zeichen)');

// Hashtags saeubern: LinkedIn bricht ein Hashtag am ersten Sonderzeichen ab.
function cleanTag(t){
  let s = String(t).replace(/^#+/, '');
  s = s.replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss')
       .replace(/Ä/g,'Ae').replace(/Ö/g,'Oe').replace(/Ü/g,'Ue');
  s = s.replace(/[^A-Za-z0-9]/g, '');
  return s ? ('#' + s) : '';
}
const rawTags = String(c.linkedin_hashtags||'').split(/\s+/).map(t => t.trim()).filter(t => t.indexOf('#') === 0);
const tags = [...new Set(rawTags.map(cleanTag).filter(Boolean))];
if (rawTags.length > 3) soft.push('Mehr als 3 Hashtags (' + rawTags.length + '), auf 3 gekuerzt');
if (tags.length === 0) soft.push('Keine verwertbaren Hashtags geliefert');
if (rawTags.join(' ') !== tags.join(' ')) soft.push('Hashtags bereinigt (Sonderzeichen entfernt)');

const igTags = [...new Set(String(c.instagram_hashtags||'').split(/\s+/).map(t=>t.trim()).filter(t=>t.indexOf('#')===0).map(cleanTag).filter(Boolean))];

const all = issues.concat(soft);
return [{ json: Object.assign({}, c, {
  linkedin_hashtags: tags.slice(0,3).join(' '),
  instagram_hashtags: igTags.slice(0,8).join(' '),
  qa_passed: issues.length === 0,
  qa_issues: all.join(' | '),
  qa_issue_count: all.length
}) }];

const p = $('Redaktions-Check').first().json;
const done = !!p.qa_passed;

// Bestandener Text -> Use-Case ist verbraucht ('used').
// Durchgefallener Text -> 'rework'. Wichtig: NICHT auf 'new' lassen,
// sonst zieht der naechste Lauf denselben schwachen Use-Case erneut
// und der Slot beisst sich daran fest.
return [{ json: {
  mi_id: (done && p.mi_id && p.mi_id !== '__none__') ? p.mi_id : '__none__',
  uc_id: (p.uc_id && p.uc_id !== '__none__') ? p.uc_id : '__none__',
  uc_status: done ? 'used' : 'rework',
  qa_passed: done,
  qa_issues: String(p.qa_issues || ''),
  finished_at: $now.toISO()
} }];

// ============================================================
// Lesbarkeit und Struktur, nach dem Redaktions-Check.
//
// Die Trennung ist Absicht: Der Redaktions-Check haelt die harten
// Verbote (Marken, Links, unbelegte Zahlen, Fremdprodukte). Hier
// stehen die Regeln aus dem LinkedIn-Leitfaden zur KI-Suche. Nur
// eine davon blockiert - Stil darf einen inhaltlich richtigen Text
// nicht aufhalten.
// ============================================================
const aus = [];

for (const item of $input.all()) {
  const c = item.json || {};
  const text = String(c.linkedin_text || '');
  const firstLine = (text.split('\n').map(s => s.trim()).filter(Boolean)[0]) || '';

  const neueIssues = [];
  const neueSoft = [];

  // --- Antwort zuerst (hart) ---
  // LinkedIn kappt mobil bei "mehr anzeigen". Was danach steht, liest
  // kaum jemand. Der erste Absatz muss die Kernaussage allein tragen:
  // 30 bis 80 Woerter. Weniger ist keine Antwort, mehr ist ein
  // ausschweifender Einstieg.
  const ersterAbsatz = (text.split(/\n\s*\n/)[0] || firstLine).trim();
  const woerterErster = ersterAbsatz.split(/\s+/).filter(Boolean).length;
  if (woerterErster < 30) {
    neueIssues.push('Antwortblock zu kurz (' + woerterErster + ' Woerter, mindestens 30)');
  } else if (woerterErster > 80) {
    neueIssues.push('Antwortblock zu lang (' + woerterErster + ' Woerter, hoechstens 80)');
  }

  // --- Stilheuristik (meldet, blockiert nicht) ---
  const saetze = text.split(/[.!?]+/)
    .map(s => s.trim())
    .filter(s => s.split(/\s+/).filter(Boolean).length > 2);
  let schnitt = 0;
  if (saetze.length) {
    schnitt = saetze.reduce((s, x) => s + x.split(/\s+/).filter(Boolean).length, 0) / saetze.length;
    if (schnitt > 20) {
      neueSoft.push('Satzlaenge im Schnitt ' + schnitt.toFixed(1) + ' Woerter, empfohlen unter 20');
    }
  }

  const absaetze = text.split(/\n\s*\n/).map(a => a.trim()).filter(Boolean);
  if (absaetze.length < 3) {
    neueSoft.push('Nur ' + absaetze.length + ' Absaetze, schwer scanbar');
  }

  // --- Ergebnis mit dem des Redaktions-Checks zusammenfuehren ---
  const bisher = String(c.qa_issues || '').split(' | ').map(s => s.trim()).filter(Boolean);
  const alle = bisher.concat(neueIssues, neueSoft);

  aus.push({ json: Object.assign({}, c, {
    qa_passed: c.qa_passed === true && neueIssues.length === 0,
    qa_issues: alle.join(' | '),
    qa_issue_count: alle.length,
    qa_antwortblock_woerter: woerterErster,
    qa_satzlaenge_schnitt: Number(schnitt.toFixed(1)),
    qa_absaetze: absaetze.length
  }) });
}

return aus;

